// Define report period (last 7 days)
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

return [{
  json: {
    period_start: weekAgo.toISOString(),
    period_end: now.toISOString(),
    generated_at: now.toISOString()
  }
}];

// Compile weekly report from all data sources
const period = $('Set Report Period').first().json;
const pipeline = $('Fetch Pipeline View').all().map(i => i.json);
const cadence = $('Fetch Cadence Performance').all().map(i => i.json);
const domains = $('Fetch Domain Health').all().map(i => i.json);

// Pipeline summary
const pipelineSummary = {};
for (const row of pipeline) {
  pipelineSummary[row.status] = (pipelineSummary[row.status] || 0) + Number(row.count || 1);
}

// Calculate totals
const totalLeads = Object.values(pipelineSummary).reduce((a, b) => a + b, 0);
const inCadence = pipelineSummary['in_cadence'] || 0;
const replied = pipelineSummary['replied'] || 0;
const bounced = pipelineSummary['bounced'] || 0;
const enriched = pipelineSummary['enriched'] || 0;

// Cadence metrics
let totalSent = 0;
let totalOpened = 0;
let totalClicked = 0;
let totalReplied = 0;

for (const c of cadence) {
  totalSent += Number(c.emails_sent || 0);
  totalOpened += Number(c.emails_opened || 0);
  totalClicked += Number(c.emails_clicked || 0);
  totalReplied += Number(c.emails_replied || 0);
}

const openRate = totalSent > 0 ? ((totalOpened / totalSent) * 100).toFixed(1) : '0.0';
const clickRate = totalSent > 0 ? ((totalClicked / totalSent) * 100).toFixed(1) : '0.0';
const replyRate = totalSent > 0 ? ((totalReplied / totalSent) * 100).toFixed(1) : '0.0';

// Domain health
const domainSummary = domains.map(d => ({
  domain: d.domain,
  sent_today: d.sent_today,
  daily_limit: d.daily_limit,
  reputation: d.reputation_score,
  utilization: d.daily_limit > 0 ? ((d.sent_today / d.daily_limit) * 100).toFixed(0) + '%' : '0%'
}));

// Build report
const report = {
  period: {
    start: period.period_start,
    end: period.period_end
  },
  pipeline: {
    total_leads: totalLeads,
    by_status: pipelineSummary
  },
  email_metrics: {
    total_sent: totalSent,
    total_opened: totalOpened,
    total_clicked: totalClicked,
    total_replied: totalReplied,
    open_rate: openRate + '%',
    click_rate: clickRate + '%',
    reply_rate: replyRate + '%'
  },
  domains: domainSummary,
  alerts: []
};

// Generate alerts
if (parseFloat(openRate) < 20) {
  report.alerts.push('Open rate below 20% - check subject lines and deliverability');
}
if (parseFloat(replyRate) < 2) {
  report.alerts.push('Reply rate below 2% - review email copy');
}
for (const d of domainSummary) {
  if (d.reputation < 70) {
    report.alerts.push(`Domain ${d.domain} reputation at ${d.reputation} - consider pausing`);
  }
}
if (bounced > totalLeads * 0.05) {
  report.alerts.push(`Bounce rate above 5% (${bounced}/${totalLeads}) - review lead quality`);
}

return [{ json: report }];

// Format report as readable message for notification
const r = $input.first().json;

const lines = [
  '=== OUTBOUND WEEKLY REPORT ===',
  `Period: ${new Date(r.period.start).toLocaleDateString('pt-BR')} - ${new Date(r.period.end).toLocaleDateString('pt-BR')}`,
  '',
  'PIPELINE:',
  `  Total Leads: ${r.pipeline.total_leads}`,
  ...Object.entries(r.pipeline.by_status).map(([k, v]) => `  ${k}: ${v}`),
  '',
  'EMAIL METRICS:',
  `  Sent: ${r.email_metrics.total_sent}`,
  `  Opened: ${r.email_metrics.total_opened} (${r.email_metrics.open_rate})`,
  `  Clicked: ${r.email_metrics.total_clicked} (${r.email_metrics.click_rate})`,
  `  Replied: ${r.email_metrics.total_replied} (${r.email_metrics.reply_rate})`,
  '',
  'DOMAINS:',
  ...r.domains.map(d => `  ${d.domain}: ${d.sent_today}/${d.daily_limit} (rep: ${d.reputation})`),
];

if (r.alerts.length > 0) {
  lines.push('', 'ALERTS:');
  r.alerts.forEach(a => lines.push(`  * ${a}`));
}

return [{
  json: {
    ...r,
    formatted_text: lines.join('\n')
  }
}];
